import Footer from './components/Footer';
import ImpressumModal from './components/ImpressumModal';
import BrandingShowcase from './components/BrandingShowcase';

const App: React.FC = () => {
  const [isImpressumOpen, setIsImpressumOpen] = useState(false);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-grow">
        <Hero />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
          <div className="bg-white border-y border-gray-100 p-12 md:p-16 mb-16 relative overflow-hidden text-center">
            <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[1px] h-12 bg-blue-500"></div>
            <h2 className="text-[10px] font-black text-[#005696] uppercase tracking-[0.4em] mb-8">Status & Portfolio-Management</h2>
            <p className="text-[#002D52] text-2xl md:text-3xl leading-relaxed font-light max-w-5xl mx-auto italic">
              "PrimeClean Facility Management befindet sich derzeit in der Gründungsphase im Raum Berlin. Es werden derzeit Gespräche für zukünftige Objektübernahmen geführt."
            </p>
            <div className="mt-12 flex justify-center space-x-8 opacity-40">
               <span className="text-[9px] uppercase tracking-[0.3em] font-bold">Zuverlässigkeit</span>
               <span className="text-[9px] uppercase tracking-[0.3em] font-bold">Diskretion</span>
               <span className="text-[9px] uppercase tracking-[0.3em] font-bold">Werterhalt</span>
            </div>
          </div>
        </div>

        <Services />
        <BrandingShowcase />
        <Contact />
      </main>

      <Footer onOpenImpressum={() => setIsImpressumOpen(true)} />

      {isImpressumOpen && (
        <ImpressumModal onClose={() => setIsImpressumOpen(false)} />
      )}
    </div>
  );
};

export default App;

