import React, { useState, useEffect } from 'react';
import { PrimeCleanLogo } from './Icons';

const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        isScrolled ? 'bg-white shadow-lg py-2' : 'bg-transparent py-4'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex justify-between items-center">
        <a href="#home" className="transition-transform duration-300 hover:scale-105">
          <div className={`${!isScrolled ? 'brightness-0 invert' : ''} transition-all duration-500`}>
            <PrimeCleanLogo className={isScrolled ? "h-10 scale-90" : "h-12 scale-100"} />
          </div>
        </a>

        <nav className="hidden md:flex space-x-10">
          <a href="#home" className={`text-sm uppercase tracking-widest font-bold transition-colors hover:text-blue-500 ${isScrolled ? 'text-[#002D52]' : 'text-white'}`}>Startseite</a>
          <a href="#services" className={`text-sm uppercase tracking-widest font-bold transition-colors hover:text-blue-500 ${isScrolled ? 'text-[#002D52]' : 'text-white'}`}>Leistungen</a>
          <a href="#contact" className={`text-sm uppercase tracking-widest font-bold transition-colors hover:text-blue-500 ${isScrolled ? 'text-[#002D52]' : 'text-white'}`}>Kontakt</a>
        </nav>

        <div className="hidden lg:block">
          <a 
            href="#contact" 
            className={`px-6 py-2.5 rounded text-sm font-bold uppercase tracking-wider transition-all ${
              isScrolled 
                ? 'bg-[#005696] text-white hover:bg-[#003d6b]' 
                : 'bg-white text-[#002D52] hover:bg-blue-50'
            }`}
          >
            Angebot anfordern
          </a>
        </div>

        <div className="md:hidden">
          <button className={`${isScrolled ? 'text-[#002D52]' : 'text-white'} p-2`}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="4" x2="20" y1="12" y2="12"/><line x1="4" x2="20" y1="6" y2="6"/><line x1="4" x2="20" y1="18" y2="18"/></svg>
          </button>
        </div>
      </div>
    </header>
  );
};

export default Header;
